this.window = new Window({
  url: `http://localhost/${this.pendingHash || ''}`,
  settings: { disableJavaScriptFileLoading: true },
});
this.document = this.window.document;

// A real browser hands the app a localStorage that outlived the previous page. A happy-dom
// Window is born empty, so a reload would silently wipe the store and every persistence and
// route-restore scenario would pass against an empty app. Seed before the app executes.
if (this.pendingStorage !== undefined && this.pendingStorage !== null)
  this.window.localStorage.setItem(STORAGE_KEY, this.pendingStorage);

// Reload the way a browser does: same origin, same localStorage, same hash, fresh app.
async reloadApp() {
  if (!this.window) throw new Error('verification support: reloadApp() before the app was loaded');
  this.pendingStorage = this.window.localStorage.getItem(STORAGE_KEY);
  this.pendingHash = this.window.location.hash;
  await this.disposeApp();
  this.loadApp();
}

// Seed the store the way a returning user's browser holds it, then start the app against it.
async seedStorage(serialized) {
  this.pendingStorage = serialized;
  this.pendingHash = '';
  await this.disposeApp();
  this.loadApp();
}

// Drive the router the way a user's address bar does.

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.pendingStorage = undefined; this.pendingHash = ''; this.loadApp(); });

module.exports = { STORAGE_KEY };

