(function (window) {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;
	var STORAGE_KEY = 'todos-vanillajs';

	var document = window.document;
	var todos = [];
	var filter = 'all';
	var editingId = null;
	var sequence = 0;

	/**
	 * Read the persisted todo collection.
	 *
	 * @planks("the app is loaded with no saved todos")
	 * @planks("the app is loaded with the todos:")
	 * @returns {Array} the stored todos
	 */
	function readStore() {
		try {
			var raw = window.localStorage.getItem(STORAGE_KEY);
			var parsed = raw ? JSON.parse(raw) : [];
			return Array.isArray(parsed) ? parsed : [];
		} catch (error) {
			return [];
		}
	}

	/**
	 * Persist the todo collection under the todos-vanillajs key, carrying only the
	 * id, title and completed fields so transient editing state is never stored.
	 *
	 * @planks("the stored todos have the titles {string}")
	 * @planks("each stored todo has the keys {string}")
	 * @planks("the stored todo {string} is completed")
	 * @planks("no stored todo has an {string} key")
	 */
	function writeStore() {
		var records = todos.map(function (todo) {
			return { id: todo.id, title: todo.title, completed: todo.completed };
		});
		window.localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
	}

	/**
	 * Mint an identifier unique within this page.
	 *
	 * @returns {string} the new identifier
	 */
	function nextId() {
		sequence += 1;
		return String(Date.now()) + '-' + String(sequence);
	}

	/**
	 * Select the todos the current filter admits.
	 *
	 * @planks("the user navigates to {string}")
	 * @planks("the user clicks the filter link {string}")
	 * @returns {Array} the todos the filter admits
	 */
	function filtered() {
		if (filter === 'active') {
			return todos.filter(function (todo) {
				return !todo.completed;
			});
		}
		if (filter === 'completed') {
			return todos.filter(function (todo) {
				return todo.completed;
			});
		}
		return todos.slice();
	}

	/**
	 * Show or hide an element.
	 *
	 * @param {object} element the element to show or hide
	 * @param {boolean} visible whether the element is shown
	 */
	function setVisible(element, visible) {
		element.style.display = visible ? '' : 'none';
	}

	/**
	 * Render the whole application from the current model: the list, the empty-state
	 * visibility of the main and footer sections, the pluralized active counter, the
	 * mark-all state, the clear-completed visibility, and the selected filter link.
	 *
	 * @planks("the todo list shows the titles {string}")
	 * @planks("the todo list is empty")
	 * @planks("the {string} section is hidden")
	 * @planks("the {string} section is visible")
	 * @planks("the counter reads {string}")
	 * @planks("the counter strong tag reads {string}")
	 * @planks("the mark all as complete checkbox is checked")
	 * @planks("the mark all as complete checkbox is unchecked")
	 * @planks("the clear completed button is hidden")
	 * @planks("the clear completed button is visible")
	 * @planks("the filter link {string} is selected")
	 * @planks("the filter link {string} is not selected")
	 * @planks("the todo {string} list item has the class {string}")
	 * @planks("the todo {string} list item does not have the class {string}")
	 * @planks("the toggle of the todo {string} is checked")
	 * @planks("the todo {string} has a remove button")
	 * @planks("the todo {string} is completed")
	 * @planks("the todo {string} is active")
	 * @planks("every todo is completed")
	 * @planks("every todo is active")
	 * @planks("the edit input of the todo {string} holds {string}")
	 * @planks("the edit input of the todo {string} has focus")
	 */
	function render() {
		var list = document.querySelector('.todo-list');
		list.innerHTML = '';
		filtered().forEach(function (todo) {
			list.appendChild(renderItem(todo));
		});

		var active = todos.filter(function (todo) {
			return !todo.completed;
		}).length;
		var completed = todos.length - active;

		setVisible(document.querySelector('.main'), todos.length > 0);
		setVisible(document.querySelector('.footer'), todos.length > 0);

		var counter = document.querySelector('.todo-count');
		counter.innerHTML = '';
		var strong = document.createElement('strong');
		strong.textContent = String(active);
		counter.appendChild(strong);
		counter.appendChild(document.createTextNode(active === 1 ? ' item left' : ' items left'));

		document.querySelector('.toggle-all').checked = todos.length > 0 && active === 0;
		setVisible(document.querySelector('.clear-completed'), completed > 0);

		var hash = filter === 'all' ? '#/' : '#/' + filter;
		Array.prototype.forEach.call(document.querySelectorAll('.filters a'), function (link) {
			if (link.getAttribute('href') === hash) {
				link.classList.add('selected');
			} else {
				link.classList.remove('selected');
			}
		});

		if (editingId !== null) {
			var editing = list.querySelector('li.editing .edit');
			if (editing) {
				editing.focus();
				editing.setSelectionRange(editing.value.length, editing.value.length);
			}
		}
	}

	/**
	 * Build one todo list item, carrying the completed and editing classes, the
	 * toggle checkbox, the label, the remove button, and the edit input.
	 *
	 * @param {object} todo the todo to render
	 * @returns {object} the list item element
	 * @planks("the user double-clicks the label of the todo {string}")
	 */
	function renderItem(todo) {
		var item = document.createElement('li');
		if (todo.completed) {
			item.classList.add('completed');
		}
		if (todo.id === editingId) {
			item.classList.add('editing');
		}
		item.setAttribute('data-id', todo.id);

		var view = document.createElement('div');
		view.className = 'view';

		var toggle = document.createElement('input');
		toggle.className = 'toggle';
		toggle.type = 'checkbox';
		toggle.checked = todo.completed;

		var label = document.createElement('label');
		label.textContent = todo.title;

		var destroy = document.createElement('button');
		destroy.className = 'destroy';

		view.appendChild(toggle);
		view.appendChild(label);
		view.appendChild(destroy);

		var edit = document.createElement('input');
		edit.className = 'edit';
		edit.value = todo.title;
		edit.addEventListener('keydown', function (event) {
			var code = event.keyCode || event.which;
			if (code === ENTER_KEY) {
				commitEdit(todo.id, edit.value);
			} else if (code === ESCAPE_KEY) {
				cancelEdit();
			}
		});
		edit.addEventListener('blur', function () {
			if (editingId === todo.id) {
				commitEdit(todo.id, edit.value);
			}
		});

		item.appendChild(view);
		item.appendChild(edit);
		return item;
	}

	/**
	 * Create a todo from the new-todo input, trimming the title and ignoring an
	 * entry that is empty once trimmed.
	 *
	 * @param {string} title the raw title the user typed
	 * @planks("the user adds the todo {string}")
	 * @planks("the new todo input is empty")
	 */
	function addTodo(title) {
		var trimmed = title.trim();
		if (trimmed.length === 0) {
			return;
		}
		todos.push({ id: nextId(), title: trimmed, completed: false });
		document.querySelector('.new-todo').value = '';
		writeStore();
		render();
	}

	/**
	 * Set one todo's completed state.
	 *
	 * @param {string} id the todo identifier
	 * @param {boolean} completed the new completed state
	 * @planks("the user toggles the todo {string}")
	 */
	function toggleTodo(id, completed) {
		todos.forEach(function (todo) {
			if (todo.id === id) {
				todo.completed = completed;
			}
		});
		writeStore();
		render();
	}

	/**
	 * Remove one todo.
	 *
	 * @param {string} id the todo identifier
	 * @planks("the user clicks the remove button of the todo {string}")
	 */
	function destroyTodo(id) {
		todos = todos.filter(function (todo) {
			return todo.id !== id;
		});
		if (editingId === id) {
			editingId = null;
		}
		writeStore();
		render();
	}

	/**
	 * Enter editing mode for one todo.
	 *
	 * @param {string} id the todo identifier
	 */
	function startEditing(id) {
		editingId = id;
		render();
	}

	/**
	 * Save an edited title, trimming it and destroying the todo when the trimmed
	 * title is empty.
	 *
	 * @param {string} id the todo identifier
	 * @param {string} value the edited title
	 * @planks("the user edits the todo {string} to {string} and presses Enter")
	 * @planks("the user edits the todo {string} to {string} and blurs the input")
	 */
	function commitEdit(id, value) {
		var trimmed = value.trim();
		editingId = null;
		if (trimmed.length === 0) {
			destroyTodo(id);
			return;
		}
		todos.forEach(function (todo) {
			if (todo.id === id) {
				todo.title = trimmed;
			}
		});
		writeStore();
		render();
	}

	/**
	 * Leave editing mode, discarding the edit.
	 *
	 * @planks("the user edits the todo {string} to {string} and presses Escape")
	 */
	function cancelEdit() {
		editingId = null;
		render();
	}

	/**
	 * Set every todo to the given completed state.
	 *
	 * @param {boolean} completed the state every todo takes
	 * @planks("the user clicks the mark all as complete checkbox")
	 */
	function toggleAll(completed) {
		todos.forEach(function (todo) {
			todo.completed = completed;
		});
		writeStore();
		render();
	}

	/**
	 * Remove every completed todo.
	 *
	 * @planks("the user clicks the clear completed button")
	 */
	function clearCompleted() {
		todos = todos.filter(function (todo) {
			return !todo.completed;
		});
		writeStore();
		render();
	}

	/**
	 * Read the current filter from the location hash.
	 *
	 * @planks("the user reloads the app")
	 */
	function applyRoute() {
		var hash = window.location.hash;
		if (hash === '#/active' || hash === '#!/active') {
			filter = 'active';
		} else if (hash === '#/completed' || hash === '#!/completed') {
			filter = 'completed';
		} else {
			filter = 'all';
		}
		render();
	}

	/**
	 * Find the todo identifier the given element belongs to.
	 *
	 * @param {object} element the event target
	 * @returns {string|null} the todo identifier
	 */
	function idOf(element) {
		var item = element.closest ? element.closest('li[data-id]') : null;
		return item ? item.getAttribute('data-id') : null;
	}

	/**
	 * Wire the page controls to the model and draw the first frame.
	 *
	 * @planks("the new todo input has the {string} attribute")
	 */
	function init() {
		todos = readStore();

		document.querySelector('.new-todo').addEventListener('keydown', function (event) {
			var code = event.keyCode || event.which;
			if (code === ENTER_KEY) {
				addTodo(event.target.value);
			}
		});

		var list = document.querySelector('.todo-list');
		list.addEventListener('change', function (event) {
			if (event.target.classList.contains('toggle')) {
				toggleTodo(idOf(event.target), event.target.checked);
			}
		});
		list.addEventListener('click', function (event) {
			if (event.target.classList.contains('destroy')) {
				destroyTodo(idOf(event.target));
			}
		});
		list.addEventListener('dblclick', function (event) {
			if (event.target.tagName === 'LABEL') {
				startEditing(idOf(event.target));
			}
		});

		document.querySelector('.toggle-all').addEventListener('change', function (event) {
			toggleAll(event.target.checked);
		});
		document.querySelector('.clear-completed').addEventListener('click', function () {
			clearCompleted();
		});

		window.addEventListener('hashchange', applyRoute);
		applyRoute();
	}

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', init);
	} else {
		init();
	}
})(window);

